            }
        } else {
            return;
        }

        if (numTokens > 7) {
            if (balancesLiveScaled18[7] < _minBalance7) {
                revert MinTokenBalanceLib.TokenBalanceBelowMin(7, balancesLiveScaled18[7], _minBalance7);
            }
        } else {
            return;
        }
